 447	/// Content-sensitive identity for a rendered project section. Leptos `<For>`
 448	/// retains the child view for an unchanged key, so the user-visible label must
 449	/// participate: daemon-side project renames must replace the captured header
 450	/// even when the section's sessions and layout are otherwise unchanged.
 451	pub(crate) fn section_render_key(sec: &ProjectSection) -> String {
 452	    format!(
 453	        "{}|{}|{}|{}|{}",
 454	        sec.key,
 455	        sec.label,
 456	        section_total_sessions(sec),
 457	        section_newest_ts(sec),
 458	        section_layout_signature(sec),
 459	    )
 460	}
 461	/// The surface-origin icon for a session's `[TAG]` title prefix. The tag set
 462	/// mirrors ocean-agent's `surface_flag` (the canonical client_type → flag
 463	/// map): BRWSR/TUI/WEB/GUI/CLI/VOX/ACP/SLACK/CNVS/MOBL. Recognized surfaces
 464	/// get a designed mark; anything else falls back to the small text badge so
 465	/// future surfaces degrade legibly instead of invisibly.
 466	pub(crate) fn origin_icon(tag: &str) -> Option<AnyView> {
 467	    match tag {
 468	        "tui" | "cli" => Some(view! { <crate::icons::Terminal /> }.into_any()),
 469	        "web" => Some(view! { <crate::icons::Globe /> }.into_any()),
 470	        "brwsr" => Some(view! { <crate::icons::Puzzle /> }.into_any()),
 471	        "gui" | "desktop" | "app" => Some(view! { <crate::icons::Desktop /> }.into_any()),
 472	        "acp" => Some(view! { <crate::icons::Code /> }.into_any()),
 473	        "vox" => Some(view! { <crate::icons::Mic /> }.into_any()),
 474	        "slack" => Some(view! { <crate::icons::Slack /> }.into_any()),
 475	        "mobl" => Some(view! { <crate::icons::Smartphone /> }.into_any()),
 476	        _ => None,
 477	    }
 478	}
