 480	/// Relative time from an ISO-8601 timestamp: "2h ago", "5d ago", etc.
 481	/// Uses `js_sys::Date` for the browser's local time. Falls back to the raw
 482	/// date text when parsing fails.
 483	pub(crate) fn fmt_relative_time(updated_at: &str) -> String {
 484	    let ts = js_sys::Date::parse(updated_at);
 485	    if ts.is_nan() {
 486	        return updated_at[..updated_at.len().min(10)].to_string();
 487	    }
 488	    let diff_s = (js_sys::Date::now() - ts) / 1000.0;
 489	    if diff_s < 60.0 {
 490	        "just now".into()
 491	    } else if diff_s < 3600.0 {
 492	        format!("{}m ago", (diff_s / 60.0) as u32)
 493	    } else if diff_s < 86400.0 {
 494	        format!("{}h ago", (diff_s / 3600.0) as u32)
 495	    } else if diff_s < 604800.0 {
 496	        format!("{}d ago", (diff_s / 86400.0) as u32)
 497	    } else {
 498	        updated_at[..10].to_string()
 499	    }
 500	}
