 502	/// Session freshness: true when the timestamp is under ten minutes old.
 503	/// Drives the live dot on session rows.
 504	pub(crate) fn is_recent(updated_at: &str) -> bool {
 505	    let ts = js_sys::Date::parse(updated_at);
 506	    !ts.is_nan() && (js_sys::Date::now() - ts) < 600_000.0
 507	}
