 509	/// Split a `[TAG] rest` origin prefix off a session title. The daemon embeds
 510	/// the client surface as a bracketed prefix (`[WEB] hi`, `[TUI] PM room`);
 511	/// rendered raw it reads as slop. `[?]` (unknown client) strips without a
 512	/// badge. Titles without a well-formed prefix pass through untouched.
 513	pub(crate) fn split_origin(title: &str) -> (Option<String>, String) {
 514	    let t = title.trim();
 515	    if let Some(rest) = t.strip_prefix('[') {
 516	        if let Some(end) = rest.find(']') {
 517	            let tag = &rest[..end];
 518	            let body = rest[end + 1..].trim();
 519	            if !tag.is_empty() && tag.len() <= 8 && !body.is_empty() {
 520	                let badge = if tag == "?" {
 521	                    None
 522	                } else {
 523	                    Some(tag.to_ascii_lowercase())
 524	                };
 525	                return (badge, body.to_string());
 526	            }
 527	        }
 528	    }
 529	    (None, t.to_string())
 530	}
